package android.database.sqlite;public abstract class SQLiteOpenHelper{private static final java.util.Map<String,SQLiteDatabase> connections=new java.util.concurrent.ConcurrentHashMap<>();private final SQLiteDatabase database;public static void bindExistingForHostR31(java.io.File path,SQLiteDatabase db){SQLiteDatabase previous=connections.putIfAbsent(path.getAbsolutePath(),db);if(previous!=null&&previous!=db)throw new IllegalStateException("HOST_CONNECTION_ALREADY_BOUND");}public SQLiteOpenHelper(android.content.Context context,String name,SQLiteDatabase.CursorFactory factory,int version){database=connections.get(context.getDatabasePath(name).getAbsolutePath());if(database==null)throw new IllegalStateException("HOST_EXPLICIT_NATIVE_CONNECTION_REQUIRED");}public SQLiteDatabase getReadableDatabase(){return database;}public SQLiteDatabase getWritableDatabase(){return database;}public void setWriteAheadLoggingEnabled(boolean enabled){}public void close(){database.close();}public abstract void onCreate(SQLiteDatabase db);public abstract void onUpgrade(SQLiteDatabase db,int oldVersion,int newVersion);public void onConfigure(SQLiteDatabase db){}public void onOpen(SQLiteDatabase db){}public void onDowngrade(SQLiteDatabase db,int oldVersion,int newVersion){throw new UnsupportedOperationException("HOST_DOWNGRADE_NOT_TESTED");}}